export const PROLOGUE=[{speaker:'Ilyra · Guardiã do Farol',title:'Seu nome não deveria estar aqui.',text:'Esta lista chegou com a última caravana. Seu nome está entre os desaparecidos. As pessoas não estão sendo levadas para uma prisão: estão sendo transformadas na energia que alimenta as armas de Aster.',goal:'Descobrir quem está capturando os exilados.'},{speaker:'Borun · Mestre da Forja',title:'O metal também guarda lembranças.',text:'Eu fabriquei as primeiras correntes. Disseram que protegeriam os comboios. Agora reconheço vozes dentro do aço. Preciso da prova guardada sob o farol para desmontar a máquina sem matar quem ficou preso nela.',goal:'Encontrar provas, reconstruir sua força e libertar as memórias.'},{speaker:'Ilyra · Guardiã do Farol',title:'Ser forte não basta.',text:'Você pode tomar o lugar de Aster ou quebrar o ciclo. Primeiro, siga os registros dos exilados. Quando alcançar o Trono, cada guardião exigirá tudo que você aprendeu a construir e executar.',goal:'Seis atos, seis títulos: romper o pacto e defender um mundo sem dono.'}];
export function currentDialogue(act,step){const speakers=['Ilyra','Borun','Selene','Aeris','Selene','Ilyra'],name=speakers[act]||'Ilyra';const lines=[['A caravana deixou um registro no Acampamento dos Exilados. Comece pelas pessoas que sobreviveram.','Os nomes foram apagados da pedra. O Santuário conserva um testemunho que Aster não conseguiu destruir.','Os guardiões atacam quem tenta lembrar. Abra o caminho para os exilados.','A prova que liga o farol à máquina está na masmorra. Traga algo que as coroas não possam negar.','O comandante protege a rota das capturas. Vencê-lo encerra esta etapa da investigação.'],['Precisamos abrir a rota de fuga antes que o comboio seja vendido.','Encontre quem testemunhou meu juramento. Eu não vou esconder o que fiz.','Quebre a guarda do caminho. Os refugiados não atravessam enquanto ela estiver de pé.','A chave das correntes está sob a fortaleza.','O comandante não deixará as caravanas partirem sem lutar.'],['As duas nações receberam a mesma arma. Siga a assinatura do fornecedor.','A mentira está escrita no santuário do império.','As sentinelas defendem um soberano que já morreu.','Na masmorra, recupere a ordem que mantém esta guerra funcionando.','Desligue o guardião que alimenta o primeiro Trono.'],['Ouvi a voz da minha irmã dentro de uma lâmina. Não é uma lembrança minha.','O catálogo da forja registra quem foi preso ao metal.','Os carcereiros precisam cair antes que as memórias se dispersem.','Recupere o núcleo da fornalha. Ainda podemos libertá-las.','Enfrente o senhor da forja. Nenhuma arma vale o que ele está fazendo.'],['Os Arcontes chamam isto de proteção. É um contrato de sacrifício.','O segundo testemunho revela o nome de um dos signatários.','Rompa os servos do pacto para alcançar seu guardião.','Traga a assinatura original da cripta.','Sem seu guardião, a assinatura pode ser quebrada.'],['Aster sabe que você chegou. Ele oferece uma coroa em troca do silêncio.','As últimas testemunhas ainda podem escolher o próprio destino.','Abra a passagem. Desta vez, ninguém ficará para alimentar a máquina.','Recupere a chave que impede o reinício.','Vença a Origem. Depois, devolva aos reinos o direito de decidir.']];return{speaker:name,text:lines[act]?.[Math.min(4,step)]||'Volte para registrar o que conquistamos.'};}
export const LEGACY_TRIALS=[{tier:1,name:'Vigília da Origem',factor:1,title:'Vigia do Mundo Livre',cores:1},{tier:2,name:'Ruptura do Pacto',factor:2,title:'Rompedor do Último Pacto',cores:2},{tier:3,name:'Ascendência do Legado',factor:4,title:'Herdeiro do Mundo Livre',cores:3}];
export function recordLegacy(player,tier,seconds){const trial=LEGACY_TRIALS.find(x=>x.tier===tier);if(!trial||!Number.isFinite(seconds)||seconds<0)return null;player.legacy||={clears:{},titles:[]};const first=!player.legacy.clears[tier],old=player.legacy.clears[tier];player.legacy.clears[tier]={wins:(old?.wins||0)+1,best:Math.min(old?.best??Infinity,seconds)};if(first){player.materials||={};player.materials['Núcleo Soberano']=(player.materials['Núcleo Soberano']||0)+trial.cores;player.legacy.titles.push(trial.title);player.activeTitle=trial.title;}return{first,trial,best:player.legacy.clears[tier].best};}
